/** @vitest-environment jsdom */
// Independent Local oracle: actual ResultViewer/Home/store; synthetic offline presentation only.
import { StrictMode } from 'react';
import { act, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { beforeEach, expect, it, vi } from 'vitest';
import { ResultViewer } from './ResultViewer';
import Home from '../app/(dashboard)/home/page';
import { useExecutionStore } from '@/lib/store';
import type { Execution } from '@/types';

const ctl = vi.hoisted(() => ({
    params: new URLSearchParams(), track: vi.fn(), save: vi.fn(),
    clipboard: [] as Array<{ text: string; finish: () => void }>,
    word: [] as Array<{ document: unknown; finish: (blob: Blob) => void }>,
    pdfLoaded: false, releasePdf: () => {}, pdfText: [] as string[], pdfNames: [] as string[],
}));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (s: string) => s }) }));
vi.mock('@/lib/analytics', () => ({ trackEvent: ctl.track }));
vi.mock('jspdf', async () => {
    await new Promise<void>(resolve => { ctl.releasePdf = resolve; ctl.pdfLoaded = true; });
    return { jsPDF: class {
        internal = { pageSize: { getWidth: () => 210, getHeight: () => 297 } };
        setFontSize() {} setFont() {} setDrawColor() {} line() {} addPage() {}
        splitTextToSize(text: string) { return [text]; }
        text(text: string) { ctl.pdfText.push(text); }
        save(name: string) { ctl.pdfNames.push(name); }
    } };
});
vi.mock('docx', () => {
    function C(this: object, options: object) { Object.assign(this, options); }
    return { Document: C, Paragraph: C, TextRun: C,
        Packer: { toBlob: (document: unknown) => new Promise<Blob>(finish => ctl.word.push({ document, finish })) },
        HeadingLevel: { TITLE: 't', HEADING_1: 'h1', HEADING_2: 'h2', HEADING_3: 'h3' },
        AlignmentType: { CENTER: 'c' }, BorderStyle: { SINGLE: 's' } };
});
vi.mock('file-saver', () => ({ saveAs: ctl.save }));
vi.mock('next/navigation', () => ({ useRouter: () => ({ push: vi.fn(), replace: vi.fn() }), useSearchParams: () => ctl.params }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {} } }) }));
vi.mock('@/lib/hooks/useExecute', () => {
    const providers: never[] = []; const fetchProviders = () => {};
    return { useProviders: () => ({ providers, anyConfigured: false, fetchProviders }) };
});
vi.mock('@/components', async () => ({
    ResultViewer: (await vi.importActual<typeof import('./ResultViewer')>('./ResultViewer')).ResultViewer,
    ProcessingScreen: () => <div data-testid="local-processing" />, DynamicForm: () => null,
    TemplatePreviewModal: () => null, OnboardingTour: () => null, AppBuilderWizard: () => null,
    ProductDesignWizard: () => null, MarketingCampaignWizard: () => null, BusinessStrategyWizard: () => null,
    SecurityAssessmentWizard: () => null, ResearchProjectWizard: () => null, SystemDesignWizard: () => null,
    ContentStrategyWizard: () => null, DataAnalysisWizard: () => null,
}));
vi.mock('@/components/home/HomeBrowseExperience', () => ({ HomeBrowseExperience: () => null }));
const execution = (id: string): Execution => ({ id, templateId: 'documentation', templateName: `Template ${id}`,
    input: { subject: id }, intent: `Intent ${id}`, output: `PRIVATE_PAYLOAD_${id}`, status: 'completed',
    createdAt: new Date('2026-10-12T00:00:00Z') });
const props = (id: string) => ({ execution: execution(id), output: `PRIVATE_PAYLOAD_${id}`,
    onAccept: vi.fn(), onReject: vi.fn(), onRetry: vi.fn(), onBack: vi.fn(), onFollowUp: vi.fn() });
function menu() {
    if (!screen.queryByText(/Export Result/)) fireEvent.click(screen.getByRole('button', { name: /Export$/ }));
    return within(screen.getByText(/Export Result/).closest('.absolute') as HTMLElement);
}
const draft = () => screen.getByTestId('followup-input') as HTMLTextAreaElement;
beforeEach(() => {
    ctl.track.mockClear(); ctl.save.mockClear(); ctl.word.length = 0; ctl.clipboard.length = 0;
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: {
        writeText: (text: string) => new Promise<void>(finish => ctl.clipboard.push({ text, finish })) } });
    localStorage.clear(); useExecutionStore.setState({ executions: [], currentExecution: null });
});

it('PDF A loads after B starts Word: original PDF payload/analytics finish while B stays busy', async () => {
    const view = render(<StrictMode><ResultViewer {...props('pdf_A')} /></StrictMode>);
    fireEvent.click(menu().getByRole('button', { name: /Download PDF/ }));
    await waitFor(() => expect(ctl.pdfLoaded).toBe(true));
    view.rerender(<StrictMode><ResultViewer {...props('word_B')} /></StrictMode>);
    fireEvent.click(menu().getByRole('button', { name: /Download Word/ }));
    await waitFor(() => expect(ctl.word).toHaveLength(1));
    expect(JSON.stringify(ctl.word[0].document)).toContain('PRIVATE_PAYLOAD_word_B');
    expect(JSON.stringify(ctl.word[0].document)).not.toContain('PRIVATE_PAYLOAD_pdf_A');
    await act(async () => { ctl.releasePdf(); });
    await waitFor(() => expect(ctl.pdfNames).toHaveLength(1));
    expect(ctl.pdfText).toContain('PRIVATE_PAYLOAD_pdf_A');
    expect(ctl.pdfText.join(' ')).not.toContain('PRIVATE_PAYLOAD_word_B');
    expect(ctl.pdfNames[0]).toMatch(/^cvf-result-documentation-\d+\.pdf$/);
    expect(ctl.track).toHaveBeenCalledWith('evidence_exported', { executionId: 'pdf_A', format: 'pdf' });
    expect(screen.getByText(/Export Result/)).toBeTruthy();
    const busy = menu().getAllByRole('button', { name: /Exporting/ });
    expect(busy).toHaveLength(1); expect((busy[0] as HTMLButtonElement).disabled).toBe(true);
    const blob = new Blob(['local-word-B']);
    await act(async () => { ctl.word[0].finish(blob); });
    await waitFor(() => expect(ctl.save).toHaveBeenCalledWith(blob, expect.stringMatching(/\.docx$/)));
    await waitFor(() => expect(screen.queryByText(/Export Result/)).toBeNull());
    expect(ctl.track).toHaveBeenCalledWith('evidence_exported', { executionId: 'word_B', format: 'docx' });
    console.log('LOCAL_PDF_ORACLE ' + JSON.stringify({ pdfText: ctl.pdfText, pdfNames: ctl.pdfNames,
        wordPayload: ctl.word[0].document, analytics: ctl.track.mock.calls }));
});

it('real history A-B-A, same-run refresh, continuation and late clipboard stay in their own lifetime', async () => {
    const a = execution('history_A'); const b = execution('history_B');
    useExecutionStore.setState({ executions: [b, a], currentExecution: null });
    ctl.params = new URLSearchParams('result=history_A');
    const view = render(<StrictMode><Home /></StrictMode>);
    fireEvent.change(draft(), { target: { value: 'discard first A draft' } });
    fireEvent.click(menu().getByRole('button', { name: /Copy to Clipboard/ }));
    expect(ctl.clipboard[0].text).toContain('PRIVATE_PAYLOAD_history_A');
    ctl.params = new URLSearchParams('result=history_B'); view.rerender(<StrictMode><Home /></StrictMode>);
    fireEvent.change(draft(), { target: { value: 'discard B draft' } });
    ctl.params = new URLSearchParams('result=history_A'); view.rerender(<StrictMode><Home /></StrictMode>);
    expect(draft().value).toBe('');
    fireEvent.change(draft(), { target: { value: 'new A continuation' } });
    fireEvent.click(screen.getByLabelText('Result view'));
    view.rerender(<StrictMode><Home /></StrictMode>);
    expect(draft().value).toBe('new A continuation');
    expect(screen.queryByTestId('deliverable-pack-preview')).toBeNull();
    fireEvent.click(menu().getByRole('button', { name: /Copy to Clipboard/ }));
    await act(async () => { ctl.clipboard[0].finish(); });
    expect(menu().getByRole('button', { name: /Copy to Clipboard/ })).toBeTruthy();
    await act(async () => { ctl.clipboard[1].finish(); });
    expect(menu().getByRole('button', { name: /Copied!/ })).toBeTruthy();
    fireEvent.click(screen.getByTestId('followup-submit-btn'));
    expect(screen.getByTestId('local-processing')).toBeTruthy();
    const child = useExecutionStore.getState().executions[0];
    expect(child.parentExecutionId).toBe('history_A');
    expect(child.intent).toBe('new A continuation');
    expect(child.input._previousOutput).toBe('PRIVATE_PAYLOAD_history_A');
    expect(useExecutionStore.getState().executions.find(e => e.id === a.id)).toEqual(a);
    expect(useExecutionStore.getState().executions.find(e => e.id === b.id)).toEqual(b);
    expect(ctl.track).toHaveBeenCalledWith('followup_started', expect.objectContaining({ executionId: a.id }));
    console.log('LOCAL_HISTORY_ORACLE ' + JSON.stringify({ child, parentRowsUnchanged: true,
        clipboard: ctl.clipboard.map(c => c.text), analytics: ctl.track.mock.calls }));
});
